async function renderList() {
  app.innerHTML = '<h1>Workboard</h1><form id="create-form"><label>Project name<input name="name" type="text" autocomplete="off"></label><button type="submit">Create project</button></form><div id="alert" role="alert" hidden></div><label>Project filter<select id="project-filter"><option>Active</option><option>Archived</option></select></label><section id="projects" aria-label="Projects"></section>';
  const form = document.querySelector('#create-form'), input = form.elements.name, alert = document.querySelector('#alert');
  async function load() {
    const archived = document.querySelector('#project-filter').value === 'Archived';
    const projects = await fetch(`/api/projects?filter=${archived ? 'Archived' : 'Active'}`).then(r => r.json());
    document.querySelector('#projects').innerHTML = projects.map(p => `<div class="project-row" data-testid="project-row"><span class="project-name">${escapeHTML(p.name)}</span><span data-testid="project-summary">${p.completedCount}/${p.totalCount} completed</span><button type="button" data-open="${escapeHTML(p.id)}">Open project</button><button type="button" data-archive="${escapeHTML(p.id)}">${archived ? 'Restore project' : 'Archive project'}</button></div>`).join('');
    document.querySelectorAll('[data-open]').forEach(b => b.onclick = () => location.href = `/projects/${encodeURIComponent(b.dataset.open)}`);
